package org.nonfood.oilplants.web;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import org.nonfood.oilplants.dao.*;import java.io.*;
@WebServlet("/admin/plants/alias") public class AdminAliasServlet extends HttpServlet{protected void doPost(HttpServletRequest r,HttpServletResponse s)throws IOException{String id=r.getParameter("plantId");try{WebSupport.requireAdmin(r);long plant=Long.parseLong(id);PlantDao dao=new PlantDao();if("remove".equals(r.getParameter("action")))dao.removeAlias(plant,Long.parseLong(r.getParameter("aliasId")));else{String alias=r.getParameter("alias");String lang=r.getParameter("language");if(alias==null||alias.isBlank()||alias.length()>160||!java.util.Set.of("zh","en","other").contains(lang))throw new IllegalArgumentException("别名内容或语言无效。");dao.addAlias(plant,alias.trim(),lang);}new AuditDao().log(WebSupport.user(r).getId(),"ALIAS_CHANGE","plant",plant,"alias updated",r.getRemoteAddr());r.getSession().setAttribute("flash","别名信息已更新。");}catch(Exception e){r.getSession().setAttribute("flash","别名操作失败："+e.getMessage());}s.sendRedirect(r.getContextPath()+"/admin/plants/form?id="+id);}}
